import { cn } from "@/lib/utils";

function BadgeShell({
  children,
  className,
  dark = false,
  ...props
}: {
  children: React.ReactNode;
  className?: string;
  dark?: boolean;
} & React.HTMLAttributes<HTMLSpanElement>) {
  return (
    <span
      {...props}
      className={cn(
        "inline-flex h-9 min-w-[3.25rem] shrink-0 items-center justify-center rounded-full px-3",
        dark
          ? "bg-white/95 shadow-sm"
          : "bg-white shadow-[0_1px_8px_rgba(16,16,16,0.08)] ring-1 ring-black/[0.06]",
        className,
      )}
    >
      {children}
    </span>
  );
}

